// RegistryBrowser searches image tags across multiple configured registries.
type RegistryBrowser struct {
	registries    []config.RegistryItem
	width, height int

	// Entries, built once from config plus the group cache.
	entries []browserRegistryEntry
	rows    []pickerRow

	// Form state
	repoInput    textinput.Model
	selectedRegs map[string]bool // entry key → checked
	focusedField int

	// Results state
	tags            []MultiRegistryTag
	pendingSearches int
	// searchQuery is the name typed for the level 1 search; it fixes the order.
	searchQuery string
	// gen names the lot of requests whose answers the browser takes, and cancel
	// stops that lot (browser_flow.go).
	gen            uint64
	cancel         context.CancelFunc
	registryFilter resultFilter
	tagTable       datatable.Model[tagRow]
	scanCache      map[string]cache.ImageScanEntry

	// Level 1 (image search): the Searcher read at open (nil: the tag flow
	// only), what came back, and the table showing it.
	searcher    imagesearch.Searcher
	images      []imagesearch.Image
	searchTable datatable.Model[searchRow]

	// The router's snapshot, for the activity column and the footer: the
	// registry's runs and remembered failures, and the context they are read in.
	jobs        []jobs.Run
	failures    []jobs.Failure

